    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT report_check CHECK ((end_date >= start_date)),
    CONSTRAINT report_file_format_check CHECK (((file_format)::text = ANY ((ARRAY['PDF'::character varying, 'CSV'::character varying])::text[])))
);


