--
-- Name: severity_override; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.severity_override (
    override_id bigint NOT NULL,
    threat_id bigint NOT NULL,
    from_severity character varying(10) NOT NULL,
    to_severity character varying(10) NOT NULL,
    reason character varying(1000) NOT NULL,
    status character varying(10) DEFAULT 'PENDING'::character varying NOT NULL,
    requested_by bigint NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_by bigint,
    processed_at timestamp with time zone,
    process_comment character varying(500),
    CONSTRAINT severity_override_check CHECK (((from_severity)::text <> (to_severity)::text)),
    CONSTRAINT severity_override_check1 CHECK (((processed_by IS NULL) OR (processed_by <> requested_by))),
    CONSTRAINT severity_override_from_severity_check CHECK (((from_severity)::text = ANY ((ARRAY['CRITICAL'::character varying, 'HIGH'::character varying, 'MEDIUM'::character varying, 'LOW'::character varying, 'INFO'::character varying])::text[]))),
    CONSTRAINT severity_override_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT severity_override_to_severity_check CHECK (((to_severity)::text = ANY ((ARRAY['CRITICAL'::character varying, 'HIGH'::character varying, 'MEDIUM'::character varying, 'LOW'::character varying, 'INFO'::character varying])::text[])))
);


